#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# A wizard reads answers from the keyboard, so it needs a real terminal. Run
# through a non-interactive shell (an agent's `!` prefix, a pipe, CI) the
# prompts would hit end-of-file and the first `ask` would exit silently.
if [[ ! -t 0 ]]; then
  echo "This wizard needs an interactive terminal: open one and run" >&2
  echo "  bash $0" >&2
  exit 2
fi

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

HOST="mini"                                     # ~/.ssh/config: kyu@192.168.219.200 (home network)
REPO="Kyu-seok/two-birds-one-rope"
RUNNER_DIR='$HOME/actions-runner-two-birds'     # expanded on the mini PC
RUNNER_NAME="minipc-two-birds"
LABEL="two-birds-deploy"                        # the deploy job in .github/workflows/check.yml targets this

remote()     { ssh "$HOST" "bash -lc '$1'"; }
remote_tty() { ssh -t "$HOST" "bash -lc '$1'"; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { warn "$1"; SKIPPED+=("$1"); }

banner "Auto-deploy: a GitHub Actions runner on the mini PC"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Check the mini PC is ready"
say "The runner deploys from the copy in ~/two-birds-one-rope (set up by deploy-minipc.sh), as your user."
ssh -o ConnectTimeout=5 "$HOST" true || { warn "can't reach '$HOST': be on the home network and re-run."; exit 1; }
ok "ssh $HOST works"
if remote "docker ps >/dev/null 2>&1"; then ok "your user can run docker without sudo"
else warn "your user can't run docker without sudo. Run 'sudo usermod -aG docker \$USER' on the mini PC, log out and in, then re-run."; exit 1; fi
if remote "test -d \$HOME/two-birds-one-rope/.git"; then ok "~/two-birds-one-rope exists"
else warn "~/two-birds-one-rope is missing: run scripts/deploy-minipc.sh first."; exit 1; fi
if [[ -z "$(remote "cd \$HOME/two-birds-one-rope && git status --porcelain")" ]]; then ok "the deployed copy has no local edits, so fast-forward deploys will apply"
else fail "~/two-birds-one-rope has local edits, so deploys may fail: commit or discard them"; fi
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Download the runner"
if remote "test -f $RUNNER_DIR/config.sh"; then
  ok "the runner is already downloaded in ~/actions-runner-two-birds"
else
  version=$(gh api repos/actions/runner/releases/latest --jq .tag_name | sed 's/^v//')
  case "$(remote 'uname -m')" in
    x86_64) arch=x64 ;; aarch64|arm64) arch=arm64 ;; *) warn "unsupported CPU: $(remote 'uname -m')"; exit 1 ;;
  esac
  url="https://github.com/actions/runner/releases/download/v$version/actions-runner-linux-$arch-$version.tar.gz"
  say "Official GitHub runner v$version for linux-$arch, from github.com/actions/runner:"
  note "$url"
  if confirm "Download and unpack it into ~/actions-runner-two-birds on the mini PC?"; then
    remote "mkdir -p $RUNNER_DIR && cd $RUNNER_DIR && curl -fsSL -o runner.tar.gz $url && tar xzf runner.tar.gz && rm runner.tar.gz" \
      && ok "runner unpacked" || { warn "download failed"; exit 1; }
  else warn "Stopped before downloading."; exit 0; fi
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Register it with the repo"
if remote "test -f $RUNNER_DIR/.runner"; then
  ok "the runner is already registered"
else
  say "Registers the runner for $REPO only, named '$RUNNER_NAME' with the label '$LABEL'."
  note "The registration token comes from your gh login, is valid for an hour, and isn't shown."
  if confirm "Register it now?"; then
    token=$(gh api -X POST "repos/$REPO/actions/runners/registration-token" --jq .token) || { warn "couldn't get a registration token: are you an admin of $REPO in gh?"; exit 1; }
    remote "cd $RUNNER_DIR && ./config.sh --unattended --url https://github.com/$REPO --token $token --name $RUNNER_NAME --labels $LABEL --replace" >/dev/null \
      && ok "registered as $RUNNER_NAME" || { warn "registration failed: run ./config.sh in ~/actions-runner-two-birds by hand to see why."; exit 1; }
    unset token
  else warn "Stopped before registering."; exit 0; fi
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Run it as a service"
say "Installs the runner as a systemd service for your user, so it starts at boot. Asks for your mini PC sudo password."
if confirm "Install and start the service?"; then
  remote_tty "cd $RUNNER_DIR && (test -f .service || sudo ./svc.sh install \$USER) && sudo ./svc.sh start" \
    && ok "service running" || fail "runner service: run 'sudo ./svc.sh install \$USER && sudo ./svc.sh start' in ~/actions-runner-two-birds"
else fail "runner service not installed"; fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Check GitHub sees it"
sleep 5
status=$(gh api "repos/$REPO/actions/runners" --jq ".runners[] | select(.name==\"$RUNNER_NAME\") | .status" 2>/dev/null || true)
if [[ "$status" == "online" ]]; then ok "$RUNNER_NAME is online"
else fail "$RUNNER_NAME shows '${status:-missing}' on GitHub (Settings → Actions → Runners)"; fi
open_url "https://github.com/$REPO/settings/actions/runners"
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "The first automatic deploy"
say "The commit that added the deploy job has its deploy waiting for this runner, and it should start now."
run=$(gh run list --repo "$REPO" --workflow Check --branch main --event push --limit 1 --json databaseId --jq '.[0].databaseId')
state=$(gh run view "$run" --repo "$REPO" --json status,conclusion --jq '.status + " " + .conclusion')
if [[ "$state" == completed* && "$state" != "completed success" ]]; then
  warn "Run $run already finished as '${state#completed }': its deploy probably gave up waiting (24 h) for a runner."
  if confirm "Re-run its failed jobs now that the runner is here?"; then
    gh run rerun "$run" --repo "$REPO" --failed && sleep 5
  fi
fi
note "Watching run $run…"
if gh run watch "$run" --repo "$REPO" --exit-status; then ok "deployed by GitHub Actions"
else fail "the deploy run failed: gh run view $run --repo $REPO --log-failed"; fi
if curl -sf -o /dev/null https://twobirds.kyuships.com/; then ok "https://twobirds.kyuships.com answers"
else fail "https://twobirds.kyuships.com doesn't answer"; fi
pause

finish
say "From now on, every push to main deploys itself once Check passes. Watch it in the Actions tab."
printf '\n'
}

run_wizard "$@"; exit
